import { expect, test } from '@playwright/test';
import { existsSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const swf =
  process.env.BT3_SWF_FILE ?? resolve('../documented-bubble-tank-3/re/bt3/uncompressed.swf');
for (const native of [false, true]) {
  test(`${native ? 'SWF' : 'mock'} creator detail thumbnails shrink once and retain independent preview and clip lifetimes`, async ({
    page,
  }, testInfo) => {
    test.skip(native && !existsSync(swf), 'Supply the local research SWF.');
    const errors: string[] = [];
    page.on('pageerror', (error) => errors.push(error.message));
    await page.goto('http://127.0.0.1:3102');
    await page.getByLabel('Fixture').selectOption('creator-details-art');
    if (native) await page.getByLabel('Original SWF').setInputFiles(swf);
    else await page.getByRole('button', { name: 'Use mock assets', exact: true }).click();
    await expect(page.getByRole('status')).toContainText('Ready', { timeout: 60000 });
    const stage = page.locator('#stage');
    const proof = JSON.parse((await stage.getAttribute('data-creator-details-art'))!);
    writeFileSync(testInfo.outputPath('details-art.json'), JSON.stringify(proof, null, 2));
    const [small, large, animated] = proof.thumbnails;
    for (const row of proof.thumbnails) {
      expect(row.first.ink).toBeGreaterThan(0);
      expect(row.held).toEqual(row.first);
      expect(row.removed.ink).toBe(0);
      expect(row.reset).toEqual(row.first);
    }
    // The source never enlarges small clips; a palette preview retains full size.
    expect(small.first).toEqual(small.preview);
    expect(Math.max(large.preview.width, large.preview.height)).toBeGreaterThan(48);
    expect(Math.max(large.first.width, large.first.height)).toBeLessThanOrEqual(50);
    expect(large.first.width).toBeLessThan(large.preview.width);
    expect(animated.animated.hash).not.toBe(animated.first.hash);
    const initialRatio = animated.first.width / animated.preview.width;
    expect(
      Math.abs(animated.animated.width - animated.previewAnimated.width * initialRatio),
    ).toBeLessThan(3);
    if (native) {
      expect(proof.rows.map((row: { key: string }) => row.key)).toEqual([
        'details:static',
        'details:arrow:1',
        'details:arrow:2',
        'selection-info:icon',
        'selection-info:popup',
      ]);
      for (const row of proof.rows) expect(row.ink).toBeGreaterThan(0);
      const [panel, arrow1, arrow2, icon, popup] = proof.rows;
      // Independently recovered authored bounds plus2px raster padding per edge.
      expect(panel).toMatchObject({ x: -2.5, y: -2.5, logicalWidth: 209, logicalHeight: 190 });
      expect(icon).toMatchObject({ x: -2, y: -2, logicalWidth: 18.05, logicalHeight: 19 });
      expect(popup.logicalWidth).toBeCloseTo(149.00274658203125);
      expect(popup.logicalHeight).toBeCloseTo(65.99722290039062);
      expect(arrow1.hash).not.toBe(arrow2.hash);
      expect(arrow1.center).toEqual([51, 153, 204, 255]);
      expect(arrow2.center).toEqual([199, 102, 5, 255]);
      // The dynamic thumbnail and its mask must not be baked into static paint.
      expect(panel.thumbnail).toEqual([0, 0, 0, 191]);
    } else expect(proof.rows).toEqual([]);
    const data = await stage
      .locator('canvas')
      .evaluate((node) => (node as HTMLCanvasElement).toDataURL());
    writeFileSync(
      testInfo.outputPath(`${native ? 'native' : 'mock'}-details-art.png`),
      Buffer.from(data.split(',')[1], 'base64'),
    );
    await page.getByLabel('Fixture').selectOption('hotkey-input');
    await expect(stage).not.toHaveAttribute('data-creator-details-art');
    expect(errors).toEqual([]);
  });
}

import { expect, test } from 'bun:test';
import {
  acceptsCreatorNameInput,
  acceptsCreatorNameEdit,
  EMPTY_CREATOR_SUBMISSION,
} from '../src/game/core/creator-dialogs';
import { defaultProfile, submitCreatedTank } from '../src/game/services/profile';
import { STARTER, difficulty } from '../src/game/data/catalog';

test('creator submissions consume failed IDs without saving, awarding or mutating the profile', () => {
  const profile = { ...defaultProfile(), tanks: [STARTER], achievements: ['Existing'] };
  let current = profile;
  for (const invalid of [
    { ...STARTER, parts: [] },
    { ...STARTER, name: '' },
    { ...STARTER, author: '' },
  ]) {
    const result = submitCreatedTank(current, invalid);
    expect(result.tank).toBeNull();
    expect(result.profile.nextTankId).toBe(current.nextTankId + 1);
    expect(result.profile.tanks).toBe(current.tanks);
    expect(result.profile.achievements).toBe(current.achievements);
    current = result.profile;
  }
  const design = { ...STARTER, name: '  A Tank  ', author: "Alice O'Brien", difficulty: -12345 };
  const first = submitCreatedTank(current, design);
  expect(first.tank).toMatchObject({
    id: 'L10000004',
    name: design.name,
    author: design.author,
    difficulty: difficulty(design),
  });
  expect(first.tank?.sourceCode).toBeUndefined();
  const second = submitCreatedTank(first.profile, first.tank!);
  expect(second.tank?.id).toBe('L10000005');
  expect(second.profile.tanks).toHaveLength(3);
  expect(second.profile.tanks[1]).toBe(first.tank!);
  expect(second.profile.achievements).not.toContain('Tank Creator');
  const third = submitCreatedTank(second.profile, design);
  expect(third.profile.achievements).toEqual(['Existing', 'Tank Creator']);
  expect(profile.nextTankId).toBe(10000001);
  expect(profile.tanks).toEqual([STARTER]);
  expect(EMPTY_CREATOR_SUBMISSION).toBe('You cannot submit tanks with nothing in them...Thanks!');
});

test('creator submission checks empty strings, preserving whitespace and existing imported punctuation', () => {
  for (const name of [' ', 'Legacy: Tank']) {
    const result = submitCreatedTank(defaultProfile(), { ...STARTER, name, author: ' ' });
    expect(result.tank).toMatchObject({ name, author: ' ', id: 'L10000001' });
  }
});

test('creator name TextEvents reject entire invalid chunks rather than filtering individual characters', () => {
  expect(acceptsCreatorNameInput("AZaz09 _-'")).toBe(true);
  expect(acceptsCreatorNameInput('')).toBe(true);
  for (const incoming of ['valid!', 'line\nbreak', 'tab\t', 'é', '😀', ':', 'A.B', 'A/B'])
    expect(acceptsCreatorNameInput(incoming)).toBe(false);
});

test('browser name edit fallback validates only the inserted span around retained punctuation', () => {
  expect(acceptsCreatorNameEdit('Legacy: Tank', 'Legacy: Tank 2')).toBe(true);
  expect(acceptsCreatorNameEdit('Legacy: Tank', 'Legacy:')).toBe(true);
  expect(acceptsCreatorNameEdit('Legacy: Tank', 'Legacy: Rover')).toBe(true);
  expect(acceptsCreatorNameEdit('Legacy: Tank', 'Legacy: Tank')).toBe(true);
  expect(acceptsCreatorNameEdit('Legacy: Tank', '')).toBe(true);
  expect(acceptsCreatorNameEdit('Tank', 'Tank!')).toBe(false);
  expect(acceptsCreatorNameEdit('Tank', 'T:a!nk')).toBe(false);
  expect(acceptsCreatorNameEdit('Tank', 'T:newank')).toBe(false);
});

import { expect, test } from 'bun:test';
import { SettingsMotion, SETTINGS_SCREEN } from '../src/game/core/settings-screen';

test('pause settings use sequential local-Y gates, same-frame setters and retained exit positions', () => {
  const m = new SettingsMotion();
  m.advance(false, false);
  expect(m.settings.Title_mc.y).toBe(340.45);
  m.advance(true, false);
  expect(m.settings.Title_mc.y).toBe(289.4);
  expect(m.settings.FrameRate_mc.y).toBe(340.45);
  for (let i = 0; i < 3; i++) m.advance(true, false);
  expect(m.settings.Title_mc.y).toBe(164.85);
  expect(m.settings.FrameRate_mc.y).toBe(294.8);
  expect(m.settings.Quality_mc.y).toBe(340.45);
  const before = JSON.stringify(m.settings);
  m.advance(false, false, true);
  expect(JSON.stringify(m.settings)).toBe(before);
  m.advance(false, false);
  expect(m.settings.Title_mc.y).toBeGreaterThan(164.85);
  m.advance(true, false);
  expect(m.settings.Title_mc.y).toBeLessThan(164.85);
});
test('hotkey Back shares the Pause-row gate and returning history freezes outside settings', () => {
  const m = new SettingsMotion();
  for (let i = 0; i < 35; i++) m.advance(true, true);
  expect(m.hotkeys.Paused_mc.y).toBeGreaterThanOrEqual(400);
  expect(m.hotkeys.btnBack_mc.y).toBe(563.45);
  expect(m.hotkeys.Locked_mc.y).toBe(563.45);
  m.advance(true, true);
  // Both rows use Pause's newly stored y, independently of Back's still-parked y.
  expect(m.hotkeys.Paused_mc.y).toBe(398.8);
  expect(m.hotkeys.btnBack_mc.y).toBe(543.85);
  expect(m.hotkeys.Locked_mc.y).toBe(539.35);
  for (let i = 36; i < 120; i++) m.advance(true, true);
  expect(m.hotkeys.btnBack_mc.y).toBeLessThan(400);
  expect(m.hotkeys.Paused_mc.y).toBeLessThan(300);
  m.returning = true;
  m.advance(true, false);
  const y = m.hotkeys.Up_mc.y;
  expect(y).toBeGreaterThan(181.25);
  for (let i = 0; i < 10; i++) m.advance(false, false);
  expect(m.hotkeys.Up_mc.y).toBe(y);
  expect(SETTINGS_SCREEN.menu.settings.origin).toEqual({ x: 210, y: 90 });
  expect(SETTINGS_SCREEN.pause.settings.origin).toEqual({ x: 274.5, y: 224.5 });
});
import { expect, test } from 'bun:test';
import {
  canonicalHotkey,
  hotkeyLabel,
  hotkeyDirections,
  validHotkey,
} from '../src/game/core/hotkeys';
import { validateSettings } from '../src/game/services/profile';
import { DEFAULT_SETTINGS } from '../src/game/core/constants';

test('Flash key codes preserve punctuation, duplicate bindings and left/right modifier equivalence', () => {
  for (const code of [
    'ShiftLeft',
    'ShiftRight',
    'ControlRight',
    'Space',
    'Tab',
    'Escape',
    'Semicolon',
    'Numpad3',
    'F1',
  ])
    expect(validHotkey(code)).toBe(true);
  for (const code of ['', 'KeyZZ', 'unidentified', 'constructor'])
    expect(validHotkey(code)).toBe(false);
  expect(canonicalHotkey('ShiftRight')).toBe('ShiftLeft');
  expect(hotkeyLabel('ShiftRight')).toBe('SHIFT');
  expect(hotkeyLabel('Semicolon')).toBe(';');
  expect(hotkeyLabel('Numpad3')).toBe('NUMPAD 3');
  expect(hotkeyLabel('F1')).toBe('p'); // _-Ay's unassigned toUpperCase return preserves this quirk.
  const settings = validateSettings({
    ...DEFAULT_SETTINGS,
    h1: 'ShiftRight',
    h2: 'ShiftLeft',
    h5: 'Escape',
  });
  expect([settings.h1, settings.h2, settings.h5]).toEqual(['ShiftLeft', 'ShiftLeft', 'Escape']);
  expect(
    hotkeyDirections(new Set(['ShiftLeft']), { ...settings, h3: 'ShiftLeft', h4: 'ShiftLeft' }),
  ).toEqual({ up: true, down: false, left: true, right: false });
});
import { expect, test } from 'bun:test';
import { DEFAULT_SETTINGS } from '../src/game/core/constants';
import {
  changeSetting,
