    width: 270.05,
    fontId: 131,
    deviceFont: false,
  });
  expect(creatorDialogFrame(1).fields[0]).toMatchObject({
    initialText: 'Are you sure you want to exit without saving?\r',
    deviceFont: true,
  });
  expect(creatorDialogFrame(3).fields[0]).toMatchObject({
    name: 'data_txt',
    x: 54.05,
    y: 180.25,
    width: 437.95,
    height: 48.05,
