import type { Field, Tank, Vec } from '../core/types';
import { STAGE } from '../core/constants';
import { displayPixel } from '../core/display-values';
import type { World } from './world';

const twips = (value: number) => Math.round(displayPixel(value) * 20);
// Pinned reference render::Matrix rounds float32 transforms to nearest, ties even.
function matrixRound(value: number) {
  if (!Number.isFinite(value)) return 0;
  if (value >= 2147483648 || value < -2147483648) return -2147483648;
  const floor = Math.floor(value),
    fraction = value - floor;
  return fraction < 0.5 ? floor : fraction > 0.5 ? floor + 1 : floor % 2 === 0 ? floor : floor + 1;
}

interface ActorParent extends Vec {
  rooted: boolean;
  members: Set<Tank>;
}
/** Enemy layers survive removal of their wrapper; actors detach only on removal/reparenting. */
export class ActorParents {
  private active = new Map<Field, ActorParent>();
  private links = new WeakMap<Tank, ActorParent>();
  private avatar?: Tank;
  private rootOffset: Vec = { x: 0, y: 0 };

  sync(world: World) {
    this.avatar = world.player;
    this.rootOffset = world.mainEffects.position;
    const next = new Map<Field, ActorParent>();
    for (const { field, runtime, offset } of world.activeFields()) {
      const parent = this.active.get(field) ?? {
        x: 0,
        y: 0,
        rooted: true,
        members: new Set<Tank>(),
      };
      parent.x = displayPixel(offset.x - world.player.x);
      parent.y = displayPixel(offset.y - world.player.y);
      const members = new Set([...field.enemies, ...runtime.allies]);
      for (const tank of parent.members)
        if (!members.has(tank) && this.links.get(tank) === parent) this.links.delete(tank);
      parent.members = members;
      for (const tank of members) {
        const previous = this.links.get(tank);
        if (previous && previous !== parent) previous.members.delete(tank);
        this.links.set(tank, parent);
      }
      next.set(field, parent);
    }
    for (const [field, parent] of this.active) if (!next.has(field)) parent.rooted = false;
    this.active = next;
  }
  attach(tank: Tank, field: Field) {
    const parent = this.active.get(field);
    if (!parent) return;
    this.links.get(tank)?.members.delete(tank);
    this.links.set(tank, parent);
    parent.members.add(tank);
  }
  detach(tank: Tank) {
    this.links.get(tank)?.members.delete(tank);
    this.links.delete(tank);
  }
  hasParent = (tank: Tank) => tank === this.avatar || this.links.has(tank);
  onStage = (tank: Tank) => tank === this.avatar || this.links.get(tank)?.rooted === true;
  setAvatar(tank: Tank) {
    this.avatar = tank;
  }

  /** Active field layer -> stage Point, independent of the user's render zoom. */
  fieldGlobal(point: Vec, field: Field): Vec | null {
    const parent = this.active.get(field);
    if (!parent) return null;
    return {
      x: ((twips(point.x) + twips(parent.x) + twips(STAGE.cx + this.rootOffset.x)) | 0) / 20,
      y: ((twips(point.y) + twips(parent.y) + twips(STAGE.cy + this.rootOffset.y)) | 0) / 20,
    };
  }
  fieldLocal(point: Vec, field: Field): Vec | null {
    const parent = this.active.get(field);
    if (!parent) return null;
    return {
      x: ((twips(point.x) - twips(parent.x) - twips(STAGE.cx + this.rootOffset.x)) | 0) / 20,
      y: ((twips(point.y) - twips(parent.y) - twips(STAGE.cy + this.rootOffset.y)) | 0) / 20,
    };
  }
  /** Local Point conversion remains valid after a clip's parent detaches. */
  localToGlobal(tank: Tank, point: Readonly<Vec>): Vec {
    const radians = tank.rotation * (Math.PI / 180),
      cos = Math.fround(Math.cos(radians)),
      sin = Math.fround(Math.sin(radians)),
      x = Math.fround(twips(point.x)),
      y = Math.fround(twips(point.y)),
      rx = matrixRound(Math.fround(Math.fround(cos * x) + Math.fround(-sin * y))),
      ry = matrixRound(Math.fround(Math.fround(sin * x) + Math.fround(cos * y))),
      avatar = tank.side === 'player',
      parent = this.links.get(tank),
      rooted = avatar ? tank === this.avatar : parent?.rooted === true;
    // Avatar has its own origin during active gameplay. Collapse's separate
    // listener suspends projectile Run and resets that local pose before resuming.
    const tx = avatar ? 0 : twips(tank.x) + (parent ? twips(parent.x) : 0),
      ty = avatar ? 0 : twips(tank.y) + (parent ? twips(parent.y) : 0);
    return {
      x: ((rx + tx + (rooted ? twips(STAGE.cx + this.rootOffset.x) : 0)) | 0) / 20,
      y: ((ry + ty + (rooted ? twips(STAGE.cy + this.rootOffset.y) : 0)) | 0) / 20,
    };
  }

  /** Source parent.localToGlobal -> owner.parent.globalToLocal crosses twip Point boundaries. */
  point(target: Tank, ownerField: Field): Vec | null {
    return this.pointAt(target, target, ownerField);
  }
  /** A transformed detail or mount point, expressed in the actor parent coordinates. */
  pointAt(target: Tank, point: Vec, ownerField: Field): Vec | null {
    const to = this.active.get(ownerField);
    if (!to) return null;
    if (target === this.avatar) return { x: -to.x || 0, y: -to.y || 0 };
    const from = this.links.get(target);
    if (!from) return null;
    const twips = (value: number) => Math.round(displayPixel(value) * 20);
    const project = (value: number, origin: number, owner: number, center: number) => {
      const global = (twips(value) + twips(origin) + (from.rooted ? center * 20 : 0)) / 20;
      return (twips(global) - twips(owner) - center * 20) / 20;
    };
    return {
      x: project(point.x, from.x, to.x, STAGE.cx),
      y: project(point.y, from.y, to.y, STAGE.cy),
    };
  }
}

import type { ActorMovementState, Tank, Vec } from '../core/types';
import type { Random } from '../core/math';
import { displayPixel } from '../core/display-values';
import { FIELD_RADIUS } from '../core/constants';

/** Source _-KM vector arithmetic order, before DisplayObject coordinate assignment. */
export function actorHeading(from: Vec, to: Vec) {
  return (360 * Math.atan2(to.y - from.y, to.x - from.x)) / (2 * Math.PI);
}
export function actorDirection(angle: number, speed: number) {
  const radians = (angle * Math.PI) / 180;
  return { x: Math.cos(radians) * speed, y: Math.sin(radians) * speed };
}
const vectorLength = (v: Vec) => Math.sqrt(v.x * v.x + v.y * v.y);

export type MovingActor = Pick<
  Tank,
  'x' | 'y' | 'side' | 'design' | 'rotation' | 'radius' | 'velocity' | 'status'
> & { movement: ActorMovementState; guns?: Tank['guns'] };
export const createActorMovement = (point: Vec = { x: 0, y: 0 }): ActorMovementState => ({
  frames: 0,
  rate: 0,
  hold: 0,
  safety: false,
  lastAngle: actorHeading({ x: 0, y: 0 }, point),
  swarmPoint: null,
  wallFlower: false,
  skittish: false,
  stationary: false,
});

/** MovieClip.rotation and _-EP's single-wrap, signed opposite-direction ties. */
export function actorAngle(value: number) {
  value %= 360;
  if (value > 180) value -= 360;
  else if (value < -180) value += 360;
  return value;
}
function planTurn(t: MovingActor, point: Vec, speed: number) {
  const delta = actorAngle(actorHeading(t, point) - t.rotation);
  t.movement.frames = Math.round(Math.abs(delta) / (speed * 1.5));
  t.movement.rate = t.movement.frames > 0 ? delta / t.movement.frames : 0;
  t.movement.safety = false;
}
function dampForce(t: MovingActor) {
  if (t.velocity.x === 0 && t.velocity.y === 0) return;
  t.velocity.x *= 0.9;
  t.velocity.y *= 0.9;
  if (vectorLength(t.velocity) < 0.1) t.velocity.x = t.velocity.y = 0;
}
/** _-dL plans a wall turn without applying it until a later Move. */
function advanceTurn(t: MovingActor, scale: number, speed: number, rng: Random) {
  const m = t.movement,
    look = actorDirection(t.rotation, 30 * speed + t.radius),
    outside =
      !m.wallFlower && vectorLength({ x: t.x + look.x, y: t.y + look.y }) > FIELD_RADIUS * scale;
  if (m.frames === 0 || (outside && !m.safety)) {
    if (outside) {
      const radial = actorHeading({ x: 0, y: 0 }, t);
      if (Math.abs(radial) > 90) {
        if (radial > 0 && m.lastAngle < 0) m.lastAngle = 360;
        else if (radial < 0 && m.lastAngle > 0) m.lastAngle = -360;
      }
      const positive = radial < 0 ? radial >= m.lastAngle : radial > m.lastAngle,
        turn = positive ? rng.int(120, 180) : rng.int(-120, -180);
      m.frames = Math.round(Math.abs(turn) / (speed * 1.5));
      if (m.skittish) m.frames /= 2;
      m.rate = speed * 1.5 * (turn / Math.abs(turn));
      m.hold = m.skittish ? 10 : 30;
      m.safety = true;
      m.lastAngle = radial;
    }
  } else {
    m.frames--;
    t.rotation = actorAngle(t.rotation + m.rate);
    m.lastAngle = actorHeading({ x: 0, y: 0 }, t);
  }
}
/** EnemyAI.Move / _-Px.Move and _-2T/_-Ab/_-QH. BehaviorRun sets next-frame swarmPoint. */
export function moveActor(t: MovingActor, fieldScale: number, rng: Random, avatar?: Vec) {
  const m = t.movement,
    speed = t.design.speed * (t.status.sticky > 0 ? 0.3 : 1);
  if (t.side === 'enemy' && t.design.id.startsWith('B')) {
    if (t.design.id.charAt(1) !== '1') return;
    t.x = t.y = 0;
    const primaries = t.guns?.filter((gun) => Math.floor(gun.part.type / 1000) === 4) ?? [];
    if (primaries[0]?.aim?.rotates)
      for (const gun of primaries) if (gun.aim) gun.aim.rotates = false;
    m.frames--;
    t.rotation = actorAngle(t.rotation + m.rate);
    m.lastAngle = 0;
    if (avatar) planTurn(t, avatar, t.design.speed);
    dampForce(t);
    return;
  }
  if (t.side === 'enemy' && m.stationary) {
    t.x = displayPixel(t.x + t.velocity.x);
    t.y = displayPixel(t.y + t.velocity.y);
    dampForce(t);
    return;
  }
  const forward = actorDirection(t.rotation, speed);
  t.x = displayPixel(t.x + (forward.x + t.velocity.x));
  t.y = displayPixel(t.y + (forward.y + t.velocity.y));
  advanceTurn(t, fieldScale, speed, rng);
  if (m.hold > 0) m.hold--;
  else if (m.swarmPoint) {
    const dx = t.x - m.swarmPoint.x,
      dy = t.y - m.swarmPoint.y;
    if (m.wallFlower || dx * dx + dy * dy > 40000) planTurn(t, m.swarmPoint, speed);
  } else if (m.frames === 0 && rng.int(0, 1000) < 20) {
    // _-OJ reads the GetLength function rather than calling it; its NaN test is always false.
    const turn = rng.int(-100, 100);
    m.frames = Math.round(Math.abs(turn) / (speed * 1.5));
    m.rate = speed * 1.5 * (turn / Math.abs(turn));
    m.safety = false;
  }
  dampForce(t);
}

