});

test('Skittish facing boundary includes 90 degrees but rear targets retain the earlier point', () => {
  const tank = actor(),
    rng = new Random(1);
  let calls = 0;
  rng.next = () => {
    calls++;
    return 0;
  };
  tank.x = 10;
  tank.y = 0;
  tank.rotation = 0;
  tickSkittish(tank, { x: 10, y: 50 }, rng);
