});

test('Skittish positive wrap bug retains a rear point while the negative wrap accepts its mirror', () => {
  const tank = actor(),
    rng = new Random(1);
  let calls = 0;
  rng.next = () => {
    calls++;
    return 0.5;
  };
  tank.x = tank.y = 0;
  tank.rotation = -180;
  setPursuitPoint(tank, { x: 1, y: 2 });
