test('Skittish chooses origin-centered 700px escape, inclusive offset and outward sign', () => {
  for (const [draw, offset] of [
    [0, 90],
    [1, 110],
  ]) {
    for (const [y, sign] of [
      [100, 1],
      [-100, -1],
    ]) {
