import type { BehaviorTargetState, Tank } from '../core/types';
import type { Random } from '../core/math';
import type { BehaviorPopulation } from './behavior-targets';

/** Source null MovieClip read aborts the current Main.Run listener, not the stage clock. */
export class HealerTargetReadError extends Error {
  constructor() {
    super('Healer AcquireTarget read a missing ally');
  }
}
/** EBehaviorHealer.AcquireTarget; a held reference returns before master/population checks. */
export function acquireHealerTarget(
  state: BehaviorTargetState,
  owner: Tank,
  population: BehaviorPopulation,
  rng: Random,
) {
  if (state.target) return state.target;
  state.master = owner.side;
  if (state.master === 'enemy') {
    for (const candidate of population.enemies)
      if (candidate !== owner && candidate.life < candidate.maxLife) {
        state.target = candidate;
        break;
      }
  } else if (state.master === 'ally') {
    let candidate = population.avatar;
    if (candidate.life === candidate.maxLife)
      for (let index = 0; index < population.allies.length; index++) {
        candidate = population.allies[rng.int(1, population.allies.length)];
        if (candidate === owner) continue;
        if (!candidate) throw new HealerTargetReadError();
        if (candidate.life < candidate.maxLife) break;
      }
    state.target = candidate;
  }
  return state.target;
}

import { expect, test } from 'bun:test';
import { STARTER } from '../src/game/data/catalog';
import { Random } from '../src/game/core/math';
import { createTank } from '../src/game/simulation/tank';
import { createBehaviorTarget } from '../src/game/simulation/behavior-targets';
import { acquireHealerTarget, HealerTargetReadError } from '../src/game/simulation/healer-target';
import { healerPatient, tickHealer, tickHealingBeam } from '../src/game/simulation/healing';
import { World, emptyInput } from '../src/game/simulation/world';
import { StageRuntime } from '../src/game/services/stage-runtime';
function actor(uid: number, side: 'ally' | 'enemy' | 'player' = 'ally', life = 100) {
  return createTank(
    uid,
    { ...STARTER, avatar: side === 'player', speed: 0, life: 100, parts: [] },
    side,
    0,
    0,
    100,
    life,
  );
}
function population() {
  const owner = actor(2),
    avatar = actor(1, 'player');
  return {
    owner,
    avatar,
    enemies: [actor(3, 'enemy'), actor(4, 'enemy', 20)],
    allies: [owner, actor(5, 'ally', 20)],
  };
}
function random(...draws: number[]) {
  const rng = new Random(1);
  let calls = 0;
  rng.next = () => {
    if (calls >= draws.length) throw new Error('extra draw');
    return draws[calls++];
  };
  return { rng, calls: () => calls };
}
function live(side: 'ally' | 'enemy' = 'enemy') {
  const world = new World([], [], 1);
  world.progression.level = 6;
  world.rng.next = () => 0.5;
  const owner = createTank(
    100,
    {
      ...STARTER,
      avatar: false,
      speed: 0,
      life: 100,
      parts: [{ ...STARTER.parts[1], x: 0, y: 0, type: 6002 }],
    },
    side,
    -100,
    0,
  );
  owner.movement.frames = 10;
  const patient = actor(101, side, 50);
  patient.x = 100;
  world.field.enemies = side === 'enemy' ? [owner, patient] : [];
  world.allies = side === 'ally' ? [owner, patient] : [];
  world.field.cleared = false;
  world.actorParents.sync(world);
  return { world, owner, patient, gun: owner.guns[0] };
}

